import{_ as t,o as i,c as s,a5 as n}from"./chunks/framework.CsGesDJn.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-19-add-workspace-member/report3_spec.md","filePath":"feature/agency-workspace/3-4-19-add-workspace-member/report3_spec.md"}'),r={name:"feature/agency-workspace/3-4-19-add-workspace-member/report3_spec.md"};function o(a,e,l,h,d,p){return i(),s("div",null,[...e[0]||(e[0]=[n("<p><strong>3.4.19 Add Workspace Member</strong></p><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace adds a member, either by inviting an email address or by assigning a user who already belongs to the Agency.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Brings people into the Workspace with the right role, either by inviting them by email or by directly assigning people who are already in the Agency.</li><li><strong>Interface</strong>: &quot;Add Member&quot; action on the members screen, offering two paths - &quot;Invite by email&quot; and &quot;Assign from Agency&quot;.</li><li><strong>Data Processing</strong>: For an invitation the system records a pending invitation and sends an email; for an assignment the system creates active memberships immediately and reports which users were added and which were skipped because they were already active members.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Add Workspace Member Screen:</p><ul><li>An &quot;Add Member&quot; action on the members screen.</li><li>An &quot;Invite by email&quot; tab with email, role, and an optional note.</li><li>An &quot;Assign from Agency&quot; tab listing existing Agency members with a role choice per person.</li><li>After an assignment, the result shows the members added and a notice for the users skipped because they were already members.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity. For an invitation: email and role. For an assignment: at least one entry of {userId, role}.</li><li><strong>Input optional</strong>: note (invitation only).</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the count of active MANAGERs in the Workspace; whether the email already has an active membership or a pending invitation; the Agency membership of each assigned user.</li><li><strong>Output</strong>: for an invitation, an acknowledgement with no content. For an assignment, the members added - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive - together with skippedUserIds. Role is one of MANAGER, CREATOR, CLIENT.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-27</strong>: Invite path - only MANAGER may invite; an already-active member cannot be re-invited (409 ALREADY_IN_WORKSPACE, checked first); a second invite is blocked while a pending unexpired invitation exists for the same email (409 INVITATION_ALREADY_PENDING, checked second); the invitation token is a random UUID with an expiry window.</li><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. The role check (MANAGER required) runs before any service-level guard.</li><li><strong>BR-02</strong>: The invitation path does not create a membership immediately - it records a pending invitation that the invitee must accept before becoming a member.</li><li><strong>BR-05</strong>: Requesting the MANAGER role while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, checked third, on both paths.</li><li><strong>BR-06</strong>: The assignment path creates active memberships immediately and needs no acceptance step.</li><li><strong>BR-07</strong>: An assignment entry whose user already has an active membership is skipped without error and reported in skippedUserIds; the rest of the batch still runs.</li><li><strong>BR-08</strong>: An assignment entry whose user is not a member of the Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li><strong>BR-09</strong>: An assignment entry whose user record does not exist -&gt; USER_NOT_FOUND.</li><li><strong>BR-31</strong>: There are three workspace roles - MANAGER, CREATOR, CLIENT; there is no Workspace-level OWNER (OWNER exists only at Agency level). Invited or assigned roles must be one of these three.</li><li><strong>BR-32</strong>: Role assignment happens at invite time; the role is stored on the invitation and carried to the member row on acceptance.</li><li><strong>BR-11</strong>: Roles are independent per Workspace - the same user may hold a different role in another Workspace of the same Agency.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Display: <strong>MSG39</strong>.</li><li>email empty -&gt; Display: <strong>MSG02</strong>.</li><li>role empty -&gt; Display: <strong>MSG02</strong>.</li><li>Invitation: email must be a well-formed email address; otherwise Display: <strong>MSG04</strong>.</li><li>Invitation: role must be one of MANAGER, CREATOR, CLIENT; otherwise Display: <strong>MSG95</strong>.</li><li>Assignment: the member list must contain at least one entry; otherwise 400 VALIDATION_ERROR.</li><li>Assignment: every userId must belong to an Agency member; otherwise 403 NOT_AGENCY_MEMBER.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>MANAGER opens the members screen and chooses &quot;Add Member&quot;.</li><li>On the invite path, the MANAGER enters an email, a role, and an optional note; on the assign path, the MANAGER picks one or more existing Agency members and a role for each.</li><li>System confirms the caller holds the MANAGER role in the Workspace; otherwise the request fails with 403 FORBIDDEN.</li><li>Invite path: system normalises the email, checks for an existing active membership and for a pending invitation, and applies the single-MANAGER rule when the role is MANAGER.</li><li>Invite path: system records a pending invitation with an expiry and sends the invitation email; toast <strong>MSG33</strong>.</li><li>Assign path: system validates each entry against Agency membership, skips users who are already active members, applies the single-MANAGER rule, and creates active memberships immediately.</li><li>Assign path: system returns the members added together with the identifiers of the users skipped.</li><li>Screen refreshes the member list with the members added and can show a notice for the skipped users.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the MANAGER of the Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The screen blocks the action.</li><li>4.a1: Invitation for an email that already has an active membership -&gt; 409 ALREADY_IN_WORKSPACE, toast <strong>MSG34</strong>. 4.a2: The MANAGER checks the existing member list instead of re-inviting.</li><li>4.b1: Invitation for an email that already has a pending, unexpired invitation -&gt; 409 INVITATION_ALREADY_PENDING, toast <strong>MSG35</strong>. 4.b2: The MANAGER waits for the pending invitation to be accepted or expire.</li><li>4.c1: MANAGER role requested while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, Display: <strong>MSG95</strong>. 4.c2: The MANAGER picks CREATOR or CLIENT instead, or hands over the MANAGER role first.</li><li>Assignment entry whose user is outside the Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li>Assignment entry whose user does not exist -&gt; USER_NOT_FOUND.</li><li>Assignment where some users are already active members -&gt; those identifiers appear in skippedUserIds, no error is raised, and the rest of the batch is processed.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Invite path: a pending invitation exists for the email with an expiry date, and the invitation email has been dispatched.</li><li>Assign path: active membership rows exist for every valid entry, and the identifiers of the skipped users have been reported.</li><li>The Workspace still has exactly one active MANAGER.</li></ul>",14)])])}const m=t(r,[["render",o]]);export{c as __pageData,m as default};
